tape( 'the function evaluates the Bessel function of the first kind of order one (medium positive values)', function test( t ) {
	var expected;
	var x;
	var y;
	var e;
	var i;

	expected = mediumPositive.expected;
	x = mediumPositive.x;
	for ( i = 0; i < x.length; i++ ) {
		y = j1( f32( x[ i ] ) );
		e = f32( expected[ i ] );

		// Larger ULP due to reduced single-precision sin/cos precision near the periodic zeros of J1:
		t.strictEqual( isAlmostSameValuef( y, e, 392 ), true, 'returns expected value' );
	}
	t.end();
});

